const TEST_SECONDS = 15 * 60;
const PASSAGES = [{"id":1,"level":"","title":"Passage 1","teacherTitle":"PASSAGE 1","wordCountTarget":null,"paragraphs":["To all staff","The hospital is trying to make the following changes, which will come into effect from 1st April.","Car Park A will stay as a staff car park, but, to encourage car sharing, it will only be available to cars containing 3 passengers or more. This rule will be in place between 7 a.m. and 6 p.m. A car park attendant will monitor users. Note that cars do not have to leave the car park with three passengers. The parking fee will remain at the current price of £1 an hour up to a maximum of £5 per day. If you are interested in car sharing and wish to find members of staff who live in your area or along your route, please click on the link on the human resources page of the hospital website. Car Park C, previously a staff-only car park, will now be open to visitors at the increased cost of £2/hour up to 5 hours, and £1 an hour after that. These new rates will also apply to staff/visitor Car Park E. Car Park B will only be open to blue card holders. Only senior and emergency staff are eligible for this card.","Car Park D will no longer be in use, as it will make away for an improved bus park. The current bus service (Service 56D) from the city center will be replaced by two services. The service will be available to staff, patients and visitors alike. Service 57A will run from Hebdon Town center Hebden Station, Critchley Park and Ride, Grafton Street, Portchester City Centre (Bus Stop D on Mill Yard) to the hospital. The service will run 24 hours a day every 20 minutes between 7 a.m. and 7 p.m. and once an hour during the night. There will also be an improved lock-up shed for bicycles and motorcycles in the former car park D. Hospital staff may wish to take advantage of the voucher giving 50% off all cycles and cycle accessories bought from Perkin’s Wheels, which is downloadable from the Human Resources website. Note that you will have to show your staff ID card at the store when making purchases. There will be a fix-it session once a fortnight in car park D on Fridays at 2 p.m. – 5 p.m. At this time, bicycle mechanics from Perkin’s Wheels will give advice on bicycle upkeep and make minor bicycle repair free of charge.","We hope you will take advantages of these schemes."],"references":[{"p":2,"start":140,"end":149,"text":"This rule"},{"p":2,"start":219,"end":226,"text":"monitor"}],"questions":[{"n":1,"displayN":1,"section":"Reading Questions","text":"What is the main topic of the passage?","options":{"A":"Changes to hospital parking","B":"Bicycle repair techniques","C":"Hospital visitor regulations","D":"Employee salary benefits"},"answer":"A","evidencePhrases":[{"p":1,"start":0,"end":52,"text":"The hospital is trying to make the following changes"}],"evidenceExplanation":"The hospital is trying to make the following changes","enExplanation":"The passage states: “The hospital is trying to make the following changes”. This supports option A (Changes to hospital parking) in the context of the question.","viExplanation":"Bài đọc thông báo các thay đổi liên quan đến bãi đỗ xe và phương tiện đi lại của bệnh viện.","type":""},{"n":2,"displayN":2,"section":"Reading Questions","text":"Under the rules, staff can only park in car park A at noon if …","options":{"A":"they hold a blue card","B":"there are three people in the car","C":"they stay for a maximum of 5 hours","D":"they stay for a maximum of 6 hours"},"answer":"B","evidencePhrases":[{"p":2,"start":73,"end":138,"text":"it will only be available to cars containing 3 passengers or more"}],"evidenceExplanation":"it will only be available to cars containing 3 passengers or more","enExplanation":"The passage states: “it will only be available to cars containing 3 passengers or more”. This supports option B (there are three people in the car) in the context of the question.","viExplanation":"Car Park A chỉ cho phép xe có từ 3 hành khách trở lên trong khung giờ quy định.","type":""},{"n":3,"displayN":3,"section":"Reading Questions","text":"The cost to park in Car park A for 4 hours will be …","options":{"A":"£1","B":"£4","C":"£5","D":"£6"},"answer":"B","evidencePhrases":[{"p":2,"start":306,"end":368,"text":"The parking fee will remain at the current price of £1 an hour"}],"evidenceExplanation":"The parking fee will remain at the current price of £1 an hour","enExplanation":"The passage states: “The parking fee will remain at the current price of £1 an hour”. This supports option B (£4) in the context of the question.","viExplanation":"Phí là £1/giờ nên 4 giờ tương đương £4.","type":""},{"n":4,"displayN":4,"section":"Reading Questions","text":"After April 1st, Car Park C will be for …","options":{"A":"staff only","B":"visitors only","C":"staff and visitors","D":"neither staff nor visitors"},"answer":"C","evidencePhrases":[{"p":2,"start":592,"end":666,"text":"Car Park C, previously a staff-only car park, will now be open to visitors"}],"evidenceExplanation":"Car Park C, previously a staff-only car park, will now be open to visitors","enExplanation":"The passage states: “Car Park C, previously a staff-only car park, will now be open to visitors”. This supports option C (staff and visitors) in the context of the question.","viExplanation":"Sau ngày 1/4, Car Park C phục vụ cả nhân viên và khách.","type":""},{"n":5,"displayN":5,"section":"Reading Questions","text":"The cost to park in Car Park C for 8 hours will be …","options":{"A":"£8","B":"£13","C":"£18","D":"£20"},"answer":"B","evidencePhrases":[{"p":2,"start":692,"end":740,"text":"£2/hour up to 5 hours, and £1 an hour after that"}],"evidenceExplanation":"£2/hour up to 5 hours, and £1 an hour after that","enExplanation":"The passage states: “£2/hour up to 5 hours, and £1 an hour after that”. This supports option B (£13) in the context of the question.","viExplanation":"5 giờ đầu tính £10, 3 giờ tiếp theo £3, tổng £13.","type":""},{"n":6,"displayN":6,"section":"Reading Questions","text":"The cost to park in Car Park E for 4 hours will be …","options":{"A":"£4","B":"£7","C":"£8","D":"£10"},"answer":"C","evidencePhrases":[{"p":2,"start":742,"end":801,"text":"These new rates will also apply to staff/visitor Car Park E"}],"evidenceExplanation":"These new rates will also apply to staff/visitor Car Park E","enExplanation":"The passage states: “These new rates will also apply to staff/visitor Car Park E”. This supports option C (£8) in the context of the question.","viExplanation":"Car Park E áp dụng mức £2/giờ, nên 4 giờ là £8.","type":""},{"n":7,"displayN":7,"section":"Reading Questions","text":"The word “This rule” in the passage refers to …","options":{"A":"The requirement that only blue card holders may park in Car Park B","B":"The rule that Car Park A is available only to cars containing three or more passengers between 7 a.m. and 6 p.m.","C":"The parking fee of £1 per hour","D":"The requirement to use the hospital website"},"answer":"B","evidencePhrases":[{"p":2,"start":140,"end":191,"text":"This rule will be in place between 7 a.m. and 6 p.m"}],"evidenceExplanation":"This rule will be in place between 7 a.m. and 6 p.m","enExplanation":"The passage states: “This rule will be in place between 7 a.m. and 6 p.m”. This supports option B (The rule that Car Park A is available only to cars containing three or more passengers between 7 a.m. and 6 p.m.) in the context of the question.","viExplanation":"“This rule” đề cập quy định xe phải có ít nhất 3 người.","type":""},{"n":8,"displayN":8,"section":"Reading Questions","text":"The word “monitor” in the passage is closest in meaning to …","options":{"A":"ignore","B":"supervise or watch carefully","C":"transport","D":"replace"},"answer":"B","evidencePhrases":[{"p":2,"start":193,"end":232,"text":"A car park attendant will monitor users"}],"evidenceExplanation":"A car park attendant will monitor users","enExplanation":"The passage states: “A car park attendant will monitor users”. This supports option B (supervise or watch carefully) in the context of the question.","viExplanation":"Monitor có nghĩa là giám sát hoặc theo dõi.","type":""},{"n":9,"displayN":9,"section":"Reading Questions","text":"Which is NOT true about Perkin’s Wheels?","options":{"A":"It sells bicycles and motorbikes.","B":"It will sell goods to staff at half price.","C":"It will fix staff member’s bikes for no charge.","D":"It doesn’t sell motorbikes."},"answer":"C","evidencePhrases":[{"p":3,"start":1089,"end":1129,"text":"make minor bicycle repair free of charge"}],"evidenceExplanation":"make minor bicycle repair free of charge","enExplanation":"The passage states: “make minor bicycle repair free of charge”. This supports option C (It will fix staff member’s bikes for no charge.) in the context of the question.","viExplanation":"Chỉ sửa chữa nhỏ miễn phí trong buổi hỗ trợ, không phải mọi sửa chữa.","type":""},{"n":10,"displayN":10,"section":"Reading Questions","text":"What is the primary purpose of the notice in this passage?","options":{"A":"To persuade staff to stop driving to work","B":"To announce and explain upcoming changes to parking and transportation facilities at the hospital","C":"To advertise Perkin’s Wheels bicycle store","D":"To encourage visitors to use hospital services"},"answer":"B","evidencePhrases":[{"p":4,"start":0,"end":49,"text":"We hope you will take advantages of these schemes"}],"evidenceExplanation":"We hope you will take advantages of these schemes","enExplanation":"The passage states: “We hope you will take advantages of these schemes”. This supports option B (To announce and explain upcoming changes to parking and transportation facilities at the hospital) in the context of the question.","viExplanation":"Mục đích là thông báo và giải thích các thay đổi mới.","type":""}]},{"id":2,"level":"","title":"Passage 2","teacherTitle":"PASSAGE 2","wordCountTarget":null,"paragraphs":["The development of genetically modified (GM) plants and animals has led to a huge global controversy. Opponents say that GM “Franken foods” are a threat to our well-being and proponents say that the risks are minimal. There is one aspect of the war over GM that is often overlooked: People grow a lot of plants that nobody eats. Anyone who wears a cotton shirt these days is suing a GM crop. Cotton is the only major non-food GM crop at present, but others are coming.","The fact that the end product of GM cotton plants is not food has not stopped the most passionate GM opponents from objecting. If GM cotton is grown in a field next to fields of non-GM cotton, they argue, then it will be hard to keep genes from being transfer from field to field. This danger, however, is not as compelling to the public as possible health hazards in food, so there is no great fury over GM cotton.","GM cotton seeds certainly have substantial advantages over the conventional kind. They produce higher yields, and they do it without the need for pesticides. Planting of GM cotton has increased fivefold since 1997; there quarter of cotton in America, and over half in China, is now GM. Farmers like it because it increases their profits.","Other options for non-food GM include new varieties of flowers with different colors or scents, tougher grasses for lawns, and plants designed to soak up pollutants from the soil. The paper industry provides another examples of the potential for GM to help produce better and cheaper products. Paper is made from pulp, and is generally made from trees. Researchers in New Zealand and Chile have been working on insect-resistant pines, and a Japanese firm has combined carrot genes with tree genes to make them grow better in poor soil.","Another interesting case is that of tobacco. It is not a food crop, of course, but it is consumed, and GM tobacco plants with both more and less nicotine have been created. Despite the absurdity of suggesting that GM tobacco might be harmful to the health of smokers, GM tobacco has still been controversial enough to present its entering the market. The tobacco plant, however, is an ideal target for GM, since its genetics are very well understood and it produces a lot of leaf. The value of the drugs that could be produced by GM tobacco is so high, many farmers could switch from growing tobacco for cigarettes to growing it for medicines. Since rising medical costs are partly due to new expensive drugs, consumers would also be happy to see drugs produced in bulk by GM tobacco."],"references":[{"p":0,"start":257,"end":261,"text":"that"},{"p":0,"start":346,"end":360,"text":"a cotton shirt"},{"p":1,"start":193,"end":197,"text":"they"},{"p":1,"start":313,"end":323,"text":"compelling"},{"p":4,"start":412,"end":415,"text":"its"}],"questions":[{"n":11,"displayN":11,"section":"Reading Questions","text":"What is the topic of the passage?","options":{"A":"Controversial GM products","B":"The hazards of GM products","C":"Non-food GM products","D":"GM cotton and tobacco"},"answer":"C","evidencePhrases":[{"p":0,"start":283,"end":327,"text":"People grow a lot of plants that nobody eats"}],"evidenceExplanation":"People grow a lot of plants that nobody eats","enExplanation":"The passage states: “People grow a lot of plants that nobody eats”. This supports option C (Non-food GM products) in the context of the question.","viExplanation":"Bài đọc tập trung vào các sản phẩm GM không phải thực phẩm.","type":""},{"n":12,"displayN":12,"section":"Reading Questions","text":"The word “that” in paragraph 1 refers to …","options":{"A":"aspect","B":"war","C":"GM","D":"risk"},"answer":"A","evidencePhrases":[{"p":0,"start":218,"end":281,"text":"There is one aspect of the war over GM that is often overlooked"}],"evidenceExplanation":"There is one aspect of the war over GM that is often overlooked","enExplanation":"The passage states: “There is one aspect of the war over GM that is often overlooked”. This supports option A (aspect) in the context of the question.","viExplanation":"That thay thế cho từ aspect.","type":""},{"n":13,"displayN":13,"section":"Reading Questions","text":"Why does the author mention “a cotton shirt” in paragraph 1?","options":{"A":"It shows that cotton is one of the most popular materials for clothing.","B":"It gives an example of a common GM product that is not a food.","C":"It gives an example of controversial surrounding GM products.","D":"It shows that the risks of GM products are minimal."},"answer":"B","evidencePhrases":[{"p":0,"start":329,"end":390,"text":"Anyone who wears a cotton shirt these days is suing a GM crop"}],"evidenceExplanation":"Anyone who wears a cotton shirt these days is suing a GM crop","enExplanation":"The passage states: “Anyone who wears a cotton shirt these days is suing a GM crop”. This supports option B (It gives an example of a common GM product that is not a food.) in the context of the question.","viExplanation":"Áo cotton là ví dụ về sản phẩm GM phi thực phẩm.","type":""},{"n":14,"displayN":14,"section":"Reading Questions","text":"Which of the following is true, according to the passage?","options":{"A":"GM cotton is less controversial than other GM products.","B":"There are several major non-food GM products at present.","C":"There have been no objections the GM cotton.","D":"GM cotton has no significant advantage over controversial cotton."},"answer":"A","evidencePhrases":[{"p":1,"start":377,"end":414,"text":"there is no great fury over GM cotton"}],"evidenceExplanation":"there is no great fury over GM cotton","enExplanation":"The passage states: “there is no great fury over GM cotton”. This supports option A (GM cotton is less controversial than other GM products.) in the context of the question.","viExplanation":"GM cotton ít gây tranh cãi hơn GM food.","type":""},{"n":15,"displayN":15,"section":"Reading Questions","text":"The word “they” in paragraph 2 refers to …","options":{"A":"GM cotton plants","B":"fields of non-GM cotton","C":"the most passionate GM opponents","D":"health hazards in food"},"answer":"C","evidencePhrases":[{"p":1,"start":78,"end":125,"text":"the most passionate GM opponents from objecting"}],"evidenceExplanation":"the most passionate GM opponents from objecting","enExplanation":"The passage states: “the most passionate GM opponents from objecting”. This supports option C (the most passionate GM opponents) in the context of the question.","viExplanation":"They chỉ những người phản đối GM.","type":""},{"n":16,"displayN":16,"section":"Reading Questions","text":"The word “compelling” in paragraph 2 is closest in meaning to …","options":{"A":"annoying","B":"interesting","C":"dangerous","D":"obvious"},"answer":"B","evidencePhrases":[{"p":1,"start":281,"end":337,"text":"This danger, however, is not as compelling to the public"}],"evidenceExplanation":"This danger, however, is not as compelling to the public","enExplanation":"The passage states: “This danger, however, is not as compelling to the public”. This supports option B (interesting) in the context of the question.","viExplanation":"Compelling mang nghĩa hấp dẫn hoặc đáng quan tâm.","type":""},{"n":17,"displayN":17,"section":"Reading Questions","text":"According to the passage, why are researchers developing GM trees?","options":{"A":"To produce more fruit","B":"To replace trees that have been cut down for paper","C":"To improve paper and make it less expensive","D":"To find a way to make paper without pulp"},"answer":"C","evidencePhrases":[{"p":3,"start":228,"end":292,"text":"the potential for GM to help produce better and cheaper products"}],"evidenceExplanation":"the potential for GM to help produce better and cheaper products","enExplanation":"The passage states: “the potential for GM to help produce better and cheaper products”. This supports option C (To improve paper and make it less expensive) in the context of the question.","viExplanation":"GM trees được phát triển để sản xuất giấy tốt và rẻ hơn.","type":""},{"n":18,"displayN":18,"section":"Reading Questions","text":"It can be inferred from the passage that GM tobacco …","options":{"A":"is already on the market","B":"produces drugs that are very expensive","C":"makes cigarettes that are not harmful to smokers’ health","D":"can have lower or higher levels of nicotine"},"answer":"D","evidencePhrases":[{"p":4,"start":103,"end":171,"text":"GM tobacco plants with both more and less nicotine have been created"}],"evidenceExplanation":"GM tobacco plants with both more and less nicotine have been created","enExplanation":"The passage states: “GM tobacco plants with both more and less nicotine have been created”. This supports option D (can have lower or higher levels of nicotine) in the context of the question.","viExplanation":"GM tobacco có thể chứa nhiều hoặc ít nicotine hơn.","type":""},{"n":19,"displayN":19,"section":"Reading Questions","text":"The word “its” in paragraph 5 refers to …","options":{"A":"market","B":"plant","C":"target","D":"GM"},"answer":"C","evidencePhrases":[{"p":4,"start":351,"end":449,"text":"The tobacco plant, however, is an ideal target for GM, since its genetics are very well understood"}],"evidenceExplanation":"The tobacco plant, however, is an ideal target for GM, since its genetics are very well understood","enExplanation":"The passage states: “The tobacco plant, however, is an ideal target for GM, since its genetics are very well understood”. This supports option C (target) in the context of the question.","viExplanation":"Its thay thế cho target.","type":""},{"n":20,"displayN":20,"section":"Reading Questions","text":"What is the main idea of this passage?","options":{"A":"Genetically modified foods are dangerous and should be banned.","B":"GM cotton is the only useful genetically modified product.","C":"Various non-food genetically modified products offer benefits but continue to generate controversy.","D":"Tobacco is the most important agricultural product in the world."},"answer":"C","evidencePhrases":[{"p":3,"start":0,"end":37,"text":"Other options for non-food GM include"}],"evidenceExplanation":"Other options for non-food GM include","enExplanation":"The passage states: “Other options for non-food GM include”. This supports option C (Various non-food genetically modified products offer benefits but continue to generate controversy.) in the context of the question.","viExplanation":"Các sản phẩm GM phi thực phẩm có lợi ích nhưng vẫn gây tranh cãi.","type":""}]},{"id":3,"level":"","title":"Passage 3","teacherTitle":"PASSAGE 3","wordCountTarget":null,"paragraphs":["Choosing a career may be one of the hardest jobs you ever have, and it must be done with care. View a career as an opportunity to do something you love, not simply as a way to earn a living. Investing the time and effort to thoroughly explore your options can mean the difference finding a stimulating and rewarding career, and moving from job to unsatisfying job in an attempt to find the right one. Work influences virtually every aspect of your life, from your choice of friends to where you live. Here are just a few of the factors to consider.","Deciding what matters most to you is essential to making the right decision. You may want to begin by assessing your likes, dislikes, strengths, and weaknesses. Think about classes, hobbies, and surroundings that you find most appealing. Ask your questions, such as, “would you like to travel? Do you want to work with children? Are you more suited to solitary or cooperative work?” There are no right or wrong answers; only you know what is important to you. Determine which job features you require, which ones you would prefer, and which ones you cannot accept. Then rank them in order of importance to you.","The setting of the job is one factor to take into account. You may not want to sit at a desk all day. If not, there are diverse occupations – building inspector, surveyor, real estate agent - that involve a great deal of time away from the office. Geographic location may be a concern, and employment in some fields is concentrated in certain regions. For example, aerospace jobs in the U.S. are most useful in California, Texas, and Washington. Advertising jobs can generally be found only in large cities. On the other hand, many industries such as hospitality, law, education, and retail sales are found in all regions of the country.","If a high salary is important to you, do not judge a career by its starting wages. Many jobs, such as insurance sales, offer relatively low in starting salaries; however, pay substantially increases along with your experience, additional training, promotions, and commission.","Don’t rule out any occupation without learning more about it. Some industries evoke positive or negative associations; The travelling life of a flight attendant appears glamorous, while that of a plumber does not. Remember that many jobs are not what they appear to be at first, and may have merits or demerits that are less obvious. Flight attendants must work long, grueling hours without sleeps, whereas plumbers can be as highly paid as some doctors. Another point to consider is that as you mature, you will likely develop new interests and skills that may point the way to new opportunities. The choice you make today need not be your final one."],"references":[{"p":1,"start":575,"end":579,"text":"them"},{"p":4,"start":78,"end":83,"text":"evoke"},{"p":4,"start":169,"end":178,"text":"glamorous"},{"p":4,"start":362,"end":397,"text":"long, grueling hours without sleeps"}],"questions":[{"n":21,"displayN":21,"section":"Reading Questions","text":"What is the main topic of the passage?","options":{"A":"Choosing a career","B":"Salary growth","C":"Job locations","D":"Flight attendants"},"answer":"A","evidencePhrases":[{"p":0,"start":0,"end":62,"text":"Choosing a career may be one of the hardest jobs you ever have"}],"evidenceExplanation":"Choosing a career may be one of the hardest jobs you ever have","enExplanation":"The passage states: “Choosing a career may be one of the hardest jobs you ever have”. This supports option A (Choosing a career) in the context of the question.","viExplanation":"Bài đọc hướng dẫn cách lựa chọn nghề nghiệp phù hợp.","type":""},{"n":22,"displayN":22,"section":"Reading Questions","text":"The word “them” in paragraph 2 refers to …","options":{"A":"questions","B":"answers","C":"features","D":"jobs"},"answer":"C","evidencePhrases":[{"p":1,"start":460,"end":579,"text":"Determine which job features you require, which ones you would prefer, and which ones you cannot accept. Then rank them"}],"evidenceExplanation":"Determine which job features you require, which ones you would prefer, and which ones you cannot accept. Then rank them","enExplanation":"The passage states: “Determine which job features you require, which ones you would prefer, and which ones you cannot accept. Then rank them”. This supports option C (features) in the context of the question.","viExplanation":"Them thay thế cho job features.","type":""},{"n":23,"displayN":23,"section":"Reading Questions","text":"According to paragraph 3, which of the following fields is not suitable for a person who does not want to live in a big city?","options":{"A":"Plumbing","B":"Law","C":"Retail sales","D":"Advertising"},"answer":"D","evidencePhrases":[{"p":2,"start":446,"end":506,"text":"Advertising jobs can generally be found only in large cities"}],"evidenceExplanation":"Advertising jobs can generally be found only in large cities","enExplanation":"The passage states: “Advertising jobs can generally be found only in large cities”. This supports option D (Advertising) in the context of the question.","viExplanation":"Ngành quảng cáo chủ yếu tập trung ở các thành phố lớn.","type":""},{"n":24,"displayN":24,"section":"Reading Questions","text":"According to the passage, which of the following is true?","options":{"A":"If you want to make a lot of money, you should not take a job with a low starting salary.","B":"If you want to make a lot of money, you should rule out all factory jobs.","C":"If you want an easy and glamorous lifestyle, you should consider becoming a flight attendant.","D":"Your initial view of certain careers may not be accurate."},"answer":"D","evidencePhrases":[{"p":4,"start":228,"end":277,"text":"many jobs are not what they appear to be at first"}],"evidenceExplanation":"many jobs are not what they appear to be at first","enExplanation":"The passage states: “many jobs are not what they appear to be at first”. This supports option D (Your initial view of certain careers may not be accurate.) in the context of the question.","viExplanation":"Ấn tượng ban đầu về nghề nghiệp có thể không chính xác.","type":""},{"n":25,"displayN":25,"section":"Reading Questions","text":"It can be inferred from the reading that …","options":{"A":"jobs in an insurance sales are generally not well-paid","B":"insurance salespeople can earn high salaries later in their careers","C":"people should constantly work toward the next promotion","D":"a starting salary should be an important consideration in choosing a career"},"answer":"B","evidencePhrases":[{"p":3,"start":102,"end":198,"text":"insurance sales, offer relatively low in starting salaries; however, pay substantially increases"}],"evidenceExplanation":"insurance sales, offer relatively low in starting salaries; however, pay substantially increases","enExplanation":"The passage states: “insurance sales, offer relatively low in starting salaries; however, pay substantially increases”. This supports option B (insurance salespeople can earn high salaries later in their careers) in the context of the question.","viExplanation":"Nhân viên bảo hiểm có thể đạt thu nhập cao hơn khi có kinh nghiệm.","type":""},{"n":26,"displayN":26,"section":"Reading Questions","text":"The word “glamorous” in paragraph 5 is closest in meaning to","options":{"A":"attractive and exciting","B":"ordinary and practical","C":"difficult and stressful","D":"serious and demanding"},"answer":"A","evidencePhrases":[{"p":4,"start":119,"end":178,"text":"The travelling life of a flight attendant appears glamorous"}],"evidenceExplanation":"The travelling life of a flight attendant appears glamorous","enExplanation":"The passage states: “The travelling life of a flight attendant appears glamorous”. This supports option A (attractive and exciting) in the context of the question.","viExplanation":"Glamorous nghĩa là hấp dẫn và thú vị.","type":""},{"n":27,"displayN":27,"section":"Reading Questions","text":"In paragraph 5, the author suggests that …","options":{"A":"you may want to change careers at some time in the future","B":"as you get older, your career will probably be less fulfilling","C":"you will be at your job for a lifetime, so choose carefully","D":"you will probably be jobless at some time in the future"},"answer":"A","evidencePhrases":[{"p":4,"start":489,"end":596,"text":"as you mature, you will likely develop new interests and skills that may point the way to new opportunities"}],"evidenceExplanation":"as you mature, you will likely develop new interests and skills that may point the way to new opportunities","enExplanation":"The passage states: “as you mature, you will likely develop new interests and skills that may point the way to new opportunities”. This supports option A (you may want to change careers at some time in the future) in the context of the question.","viExplanation":"Tác giả cho rằng có thể thay đổi nghề nghiệp trong tương lai.","type":""},{"n":28,"displayN":28,"section":"Reading Questions","text":"The word “evoke” in paragraph 5 is closest in meaning to …","options":{"A":"bring to mind","B":"be related to","C":"be different from","D":"agree on"},"answer":"A","evidencePhrases":[{"p":4,"start":62,"end":117,"text":"Some industries evoke positive or negative associations"}],"evidenceExplanation":"Some industries evoke positive or negative associations","enExplanation":"The passage states: “Some industries evoke positive or negative associations”. This supports option A (bring to mind) in the context of the question.","viExplanation":"Evoke nghĩa là gợi lên hoặc làm nhớ tới.","type":""},{"n":29,"displayN":29,"section":"Reading Questions","text":"Why does the author mention “long, grueling hours without sleeps” in paragraph 5?","options":{"A":"To emphasize the difficulty of working as a plumber","B":"To contrast the reality of a flight attendant’s job with most people’s perceptions","C":"To show that people must be willing to work hard for the career they’ve chosen","D":"To discourage readers from choosing a career as a flight attendant"},"answer":"B","evidencePhrases":[{"p":4,"start":334,"end":397,"text":"Flight attendants must work long, grueling hours without sleeps"}],"evidenceExplanation":"Flight attendants must work long, grueling hours without sleeps","enExplanation":"The passage states: “Flight attendants must work long, grueling hours without sleeps”. This supports option B (To contrast the reality of a flight attendant’s job with most people’s perceptions) in the context of the question.","viExplanation":"Ví dụ được dùng để đối chiếu nhận thức và thực tế về nghề tiếp viên.","type":""},{"n":30,"displayN":30,"section":"Reading Questions","text":"What can be inferred from the passage about career choice?","options":{"A":"People should select a career based solely on their starting salary.","B":"A career decision made today does not necessarily have to be permanent.","C":"Most people remain satisfied with the first job they choose.","D":"Personal interests are less important than geographic location."},"answer":"B","evidencePhrases":[{"p":4,"start":598,"end":650,"text":"The choice you make today need not be your final one"}],"evidenceExplanation":"The choice you make today need not be your final one","enExplanation":"The passage states: “The choice you make today need not be your final one”. This supports option B (A career decision made today does not necessarily have to be permanent.) in the context of the question.","viExplanation":"Lựa chọn nghề nghiệp hôm nay không nhất thiết là vĩnh viễn.","type":""}]},{"id":4,"level":"","title":"Passage 4","teacherTitle":"PASSAGE 4","wordCountTarget":null,"paragraphs":["New surveys suggest that the technological tools we use to make our lives easier are killing our leisure time. We are looking longer hours, taking fewer and shorter vacations (and when we do go away, we take our cell phones, PDAs, and laptops along). And, we are more stressed than ever as increased use of e-mail, cell phones, and the internet is destroying any idea of privacy and leisure.","Since the industrial Revolution, people have assumed that new labor-saving devices would free from the burden of the workplace and give them more time to grow intellectually, creatively, and socially – exploring the arts, keeping up with current events, spending more time with friends and family, and even just ‘goofing off’.","But here we are at the start of the 21st century, enjoying one of the greatest technological boom times in human history, and nothing could be further from the truth. The very tools that were supposed to liberate us have bound us to our work and study in ways that were inconceivable just a few years ago. It would seem that technology almost never does what we expect.","In ‘the old days’, the lines between work and leisure time were markedly clearer. People left their offices at a predictable time, were often completely disconnected from and out of touch with their jobs as they traveled to and from work, and were off-duty once they were home. That is no longer true. In today’s highly competitive job market, employers demand increased productivity, expecting workers to put in longer hours and to keep in touch almost constantly via tax, cell phones, e-mail, or other communications devices. As a result, employees feel the need to check in on what is going on at the office, even on days off. They feel pressured to work after hours just to catch up on everything they have to do. Workers work harder and longer, change their work task more frequently, and have more and more reasons to worry about job security.","Bosses, colleagues, family members, lovers, and friends expect instant responses to voice mail and e-mail messages. Even college students have become bound to their desks by an environment in which faculty, friends and other members of the college community increasingly do their work online. Studies of time spent on instant messaging services would probably show staggering use.","This is what technology was supposed to be doing for us. New technologies, from genetic research to the Internet, offer all sorts of benefits and opportunities. But, when new tools make life more difficult and stressful rather than easier and more meaningful – and we are, as a society, barely conscious of it – then something has gone seriously awry, both with our expectations for technology and our understanding of how it should benefit us."],"references":[{"p":2,"start":270,"end":283,"text":"inconceivable"},{"p":3,"start":108,"end":129,"text":"at a predictable time"},{"p":3,"start":630,"end":634,"text":"They"},{"p":4,"start":365,"end":375,"text":"staggering"}],"questions":[{"n":31,"displayN":31,"section":"Reading Questions","text":"This passage has probably been taken from …","options":{"A":"an advertisement","B":"a science review","C":"a political journal","D":"a fashion magazine"},"answer":"B","evidencePhrases":[{"p":0,"start":0,"end":109,"text":"New surveys suggest that the technological tools we use to make our lives easier are killing our leisure time"}],"evidenceExplanation":"New surveys suggest that the technological tools we use to make our lives easier are killing our leisure time","enExplanation":"The passage states: “New surveys suggest that the technological tools we use to make our lives easier are killing our leisure time”. This supports option B (a science review) in the context of the question.","viExplanation":"Đây có thể là một bài viết trong tạp chí khoa học.","type":""},{"n":32,"displayN":32,"section":"Reading Questions","text":"Which of the following could best serve as the title of the passage?","options":{"A":"Changes at the Workplace","B":"Research on the Roles of Computers","C":"Benefits of Technology","D":"Expectations and Plain Reality"},"answer":"D","evidencePhrases":[{"p":2,"start":325,"end":368,"text":"technology almost never does what we expect"}],"evidenceExplanation":"technology almost never does what we expect","enExplanation":"The passage states: “technology almost never does what we expect”. This supports option D (Expectations and Plain Reality) in the context of the question.","viExplanation":"Tiêu đề phù hợp nhất là Kỳ vọng và Thực tế.","type":""},{"n":33,"displayN":33,"section":"Reading Questions","text":"According to the passage, which of the following is one reason employees feel pressured to work after hours?","options":{"A":"They are required to attend evening classes.","B":"They want to learn new technological skills.","C":"They need to catch up on the large amount of work they have to do.","D":"They are encouraged to spend more time with family members."},"answer":"C","evidencePhrases":[{"p":3,"start":653,"end":716,"text":"work after hours just to catch up on everything they have to do"}],"evidenceExplanation":"work after hours just to catch up on everything they have to do","enExplanation":"The passage states: “work after hours just to catch up on everything they have to do”. This supports option C (They need to catch up on the large amount of work they have to do.) in the context of the question.","viExplanation":"Nhân viên làm thêm giờ để theo kịp khối lượng công việc.","type":""},{"n":34,"displayN":34,"section":"Reading Questions","text":"The word “inconceivable” in paragraph 3 is closest in meaning to ______.","options":{"A":"unimaginable","B":"predictable","C":"foreseeable","D":"unforgettable"},"answer":"A","evidencePhrases":[{"p":2,"start":270,"end":304,"text":"inconceivable just a few years ago"}],"evidenceExplanation":"inconceivable just a few years ago","enExplanation":"The passage states: “inconceivable just a few years ago”. This supports option A (unimaginable) in the context of the question.","viExplanation":"Inconceivable nghĩa là không thể tưởng tượng được.","type":""},{"n":35,"displayN":35,"section":"Reading Questions","text":"With the phrase “at a predictable time” the author implies that …","options":{"A":"people were unable to foresee their working hours","B":"people had to predict the time they were allowed to leave offices","C":"people wanted to be completely disconnected from their work","D":"people used to have more time and privacy after work"},"answer":"D","evidencePhrases":[{"p":3,"start":82,"end":129,"text":"People left their offices at a predictable time"}],"evidenceExplanation":"People left their offices at a predictable time","enExplanation":"The passage states: “People left their offices at a predictable time”. This supports option D (people used to have more time and privacy after work) in the context of the question.","viExplanation":"Cụm từ cho thấy trước đây mọi người có nhiều thời gian riêng hơn sau giờ làm.","type":""},{"n":36,"displayN":36,"section":"Reading Questions","text":"The word “They” in the fourth paragraph refers to …","options":{"A":"employers","B":"workers","C":"employees","D":"tasks"},"answer":"C","evidencePhrases":[{"p":3,"start":541,"end":649,"text":"employees feel the need to check in on what is going on at the office, even on days off. They feel pressured"}],"evidenceExplanation":"employees feel the need to check in on what is going on at the office, even on days off. They feel pressured","enExplanation":"The passage states: “employees feel the need to check in on what is going on at the office, even on days off. They feel pressured”. This supports option C (employees) in the context of the question.","viExplanation":"They thay thế cho employees.","type":""},{"n":37,"displayN":37,"section":"Reading Questions","text":"It can be inferred from the fourth paragraph that …","options":{"A":"employees have more freedom to decide what time they start and finish work","B":"employers are more demanding and have efficient means to monitor employees","C":"life is more relaxing with cell phones and other technological devices","D":"it is compulsory that employees go to the office, even on days off"},"answer":"B","evidencePhrases":[{"p":3,"start":344,"end":464,"text":"employers demand increased productivity, expecting workers to put in longer hours and to keep in touch almost constantly"}],"evidenceExplanation":"employers demand increased productivity, expecting workers to put in longer hours and to keep in touch almost constantly","enExplanation":"The passage states: “employers demand increased productivity, expecting workers to put in longer hours and to keep in touch almost constantly”. This supports option B (employers are more demanding and have efficient means to monitor employees) in the context of the question.","viExplanation":"Người sử dụng lao động ngày càng đòi hỏi nhiều hơn và dễ giám sát nhân viên.","type":""},{"n":38,"displayN":38,"section":"Reading Questions","text":"The word “staggering” in paragraph 5 is closest in meaning to …","options":{"A":"surprisingly large","B":"carefully measured","C":"gradually decreasing","D":"difficult to calculate"},"answer":"A","evidencePhrases":[{"p":4,"start":293,"end":379,"text":"Studies of time spent on instant messaging services would probably show staggering use"}],"evidenceExplanation":"Studies of time spent on instant messaging services would probably show staggering use","enExplanation":"The passage states: “Studies of time spent on instant messaging services would probably show staggering use”. This supports option A (surprisingly large) in the context of the question.","viExplanation":"Staggering nghĩa là rất lớn hoặc đáng kinh ngạc.","type":""},{"n":39,"displayN":39,"section":"Reading Questions","text":"What can be inferred about the author's view of modern technology?","options":{"A":"Its benefits are accompanied by unexpected drawbacks.","B":"It has completely failed to improve society.","C":"It should be avoided whenever possible.","D":"It mainly affects students rather than workers."},"answer":"A","evidencePhrases":[{"p":5,"start":114,"end":219,"text":"offer all sorts of benefits and opportunities. But, when new tools make life more difficult and stressful"}],"evidenceExplanation":"offer all sorts of benefits and opportunities. But, when new tools make life more difficult and stressful","enExplanation":"The passage states: “offer all sorts of benefits and opportunities. But, when new tools make life more difficult and stressful”. This supports option A (Its benefits are accompanied by unexpected drawbacks.) in the context of the question.","viExplanation":"Tác giả cho rằng công nghệ có lợi ích nhưng cũng kéo theo hệ quả tiêu cực.","type":""},{"n":40,"displayN":40,"section":"Reading Questions","text":"Which of the following best summarizes this passage?","options":{"A":"Technology improves convenience but often reduces leisure and increases stress.","B":"Technology creates efficiency yet frequently blurs work-life boundaries today.","C":"Technology offers benefits while simultaneously demanding greater availability everywhere.","D":"Technology advances rapidly although users struggle balancing work effectively."},"answer":"B","evidencePhrases":[{"p":5,"start":171,"end":258,"text":"new tools make life more difficult and stressful rather than easier and more meaningful"}],"evidenceExplanation":"new tools make life more difficult and stressful rather than easier and more meaningful","enExplanation":"The passage states: “new tools make life more difficult and stressful rather than easier and more meaningful”. This supports option B (Technology creates efficiency yet frequently blurs work-life boundaries today.) in the context of the question.","viExplanation":"Công nghệ tăng hiệu quả nhưng làm mờ ranh giới công việc và cuộc sống.","type":""}]}];
